python3 - <<'PYEOF'
import pathlib
ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')

p = ROOT / 'src/codegen/lower_inst/exceptions.rs'
t = p.read_text()
old = '''        if emit_trace_argument(ctx, operand).is_err() {
            // An operand whose shape has no php rendering ends the argument list rather than
            // guessing at one. php would have printed it; a wrong value would be worse.
            break;
        }'''
new = '''        if emit_trace_argument(ctx, operand).is_err() {
            // An operand whose shape has no php rendering leaves the argument list SHORT — the
            // frame still closes, so the trace reads `fn('a')` where php would have written
            // `fn('a', <something>)`. That is a smaller lie than a value invented for the shape,
            // and it is why `emit_trace_argument` refuses rather than guessing.
            break;
        }'''
assert t.count(old) == 1
t = t.replace(old, new, 1)
old = '''        // Anything else has no rendering php would recognise, so the frame stops here rather
        // than printing a value invented for it.'''
new = '''        // Anything else has no rendering php would recognise. Refusing here abandons the rest of
        // the argument list (the caller breaks out of the loop) rather than printing a value
        // invented for the shape.'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('exceptions.rs: the refusal comment says what actually happens')

p = ROOT / 'src/codegen_support/runtime/io/glob.rs'
t = p.read_text()
old = '''    emitter.instruction("bl __rt_diag_warning");                                // warnings honour the @ suppression depth
    emitter.instruction("b __rt_glob_ret");'''
new = '''    emitter.instruction("bl __rt_diag_warning");                                // warnings honour the @ suppression depth
    // Straight to the RETURN label, deliberately: `globfree()` lives at `__rt_glob_free`, which
    // merely falls through into `__rt_glob_ret`. Branching to the tail therefore never passes
    // through that call, which matters because libc `glob()` has not run and the stack `glob_t`
    // at [sp,#16] holds whatever the frame held before.
    emitter.instruction("b __rt_glob_ret");'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('glob.rs: the tail layout is documented where it is relied on')
